import 'dart:ui';import 'package:flutter_test/flutter_test.dart';import 'package:surge_wizard/core/battle_layout_v4.dart';void main(){group('HexGeometryV4',(){test('center hex burst contains seven cells away from edge',(){final g=HexGeometryV4(const Size(676,302));expect(g.burst7(const HexCoord(4,3)).length,7);});test('all standard board coordinates are valid',(){for(var c=0;c<BattleLayoutV4.columns;c++)for(var r=0;r<BattleLayoutV4.rows;r++)expect(HexCoord(c,r).isValidFor(BattleLayoutV4.columns,BattleLayoutV4.rows),isTrue);});test('hit test resolves a hex center to itself',(){final g=HexGeometryV4(const Size(676,302));const e=HexCoord(3,3);expect(g.hitTest(g.center(e)),e);});});}
